import{_ as i,l as s,o as t,c as r,v as e,p as l,x as o,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"交易成本下的组合 Constantinides","description":"","frontmatter":{"title":"交易成本下的组合 Constantinides","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/transaction-cost-portfolio-theory.md","filePath":"econ/transaction-cost-portfolio-theory.md","lastUpdated":1789023840000}'),h={name:"econ/transaction-cost-portfolio-theory.md"};function E(m,a,B,C,_,u){const n=s("Mermaid");return t(),r("div",null,[a[1]||(a[1]=e('<h1 id="交易成本下的组合-constantinides" tabindex="-1">交易成本下的组合 Constantinides <a class="header-anchor" href="#交易成本下的组合-constantinides" aria-label="Permalink to &quot;交易成本下的组合 Constantinides&quot;">​</a></h1><div class="epigraph"><p>成比例成本使连续再平衡的 Merton 权重变成无交易区间：只有偏离够大才调仓，小偏离被惰性吞掉。</p><footer>—— Constantinides, Capital Market Equilibrium with Transaction Costs, Journal of Political Economy, 1986</footer></div><p><a href="/econ/incomplete-market-pricing-bounds">上一课</a>因缺列而不能精确复制。本课菜单可以完全，但<strong>再平衡要付成比例成本</strong>。缺口是政策形状：从点状 \\(\\theta^\\ast\\) 变成区间。不把成本写成限价簿价差的估计，尽管经济含义相近——协议仍不在本栏。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Merton 常机会下 \\(\\theta\\) 每瞬都等于目标。成比例成本（买卖按价格的固定比例付费）使每一次调整有限损失。最优是：在财富–持仓状态空间里设一个无交易锥（或带），落在带内不动，碰到边界才交易到边界内侧（或到有限目标）。Constantinides（1986）在一般均衡里还问：这种惰性如何反馈进价格。缺口是承认 BS 式连续 \\(\\Delta\\) 在正成本下期望损失无穷（无限次小交易），工作策略必须是间歇的。</p><p>与 BP 保证金：那边是占用资本；这边是每次调仓的冰山成本。都可以减少交易频率。与 Glosten–Milgrom：价差是不利选择的均衡报价；这里成本可以是外生摩擦（税、物理）。接口课已经允许把价差折进持有成本——Constantinides 是那条通道的组合理论。</p><p><span class="marginnote">Constantinides, <em>JPE</em> 94(4), 1986。Davis–Norman 给出成比例成本下的奇异控制解（无交易、买、卖三区域）。本课要形状，不要控制论细节。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>状态含当前权重。HJB 在无交易区退化为偏微（只有扩散把权重带偏），在交易区退化成「立刻付成本并跳到边界」。比较静态：成本升，带宽；风险厌恶升，目标更稳但带宽的福利成本更高。均衡：若人人惰性，价格对小冲击反应钝——与过度波动的「价格太抖」对照，摩擦这一层倾向于更钝；时变 \\(m\\) 仍可以抖。不要用惰性否证 Shiller，也不要用 Shiller 否证惰性。</p>',9)),(t(),l(c,null,{default:o(()=>[p(n,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20MER%5B%22Merton%20%E7%82%B9%20%CE%B8*%22%5D%20--%3E%20COST%5B%22%E6%88%90%E6%AF%94%E4%BE%8B%E6%88%90%E6%9C%AC%22%5D%0A%20%20COST%20--%3E%20BAND%5B%22%E6%97%A0%E4%BA%A4%E6%98%93%E5%8C%BA%E9%97%B4%22%5D%0A%20%20BAND%20--%3E%20TOUCH%5B%22%E7%A2%B0%E8%BE%B9%E7%95%8C%E6%89%8D%E8%B0%83%E4%BB%93%22%5D%0A%20%20CONT%5B%22%E8%BF%9E%E7%BB%AD%20%CE%94%22%5D%20--%3E%20INF%5B%22%E6%9C%9F%E6%9C%9B%E6%88%90%E6%9C%AC%E6%97%A0%E7%A9%B7%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<p>不要把无交易区间画成盘口两档之间的空间。那是簿；这里是个人状态空间里的政策。投资者可以在区间内「对市场价格有需求为零的导数」，看起来像流动性差，来源是成本不是信息。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是固定比例的冰山对冲掉伊藤的无穷小再平衡。二次变差要求理论上不停调，线性成本对每次调收费，最优用带宽换风险暴露误差。福利损失往往小于朴素「成本乘换手」的直觉——因为最优已经大幅降低换手。加总后，市场中介看到的流量更尖、更间歇，像流动性螺旋的离散版，但不必有保证金。</p><p>不完全加成本：界更宽，因为超复制若靠高频对冲，成本把上界抬高。本课点明叠加，不计算。</p><p><span class="marginnote">固定成本（每笔固定费）给出另一类政策：更少、更大的交易。本课以成比例为主，对应买卖价差的比例部分。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不校准某市场的年换手。下一课把装置收回离散多期：消费–组合的两基金、欧拉、与连续时间极限的对照，作为本单元收束。Constantinides 的惰性在离散里变成「校准点附近的 \\(sS\\) 规则」。</p><p>后课默认：成比例交易成本 ⇒ 无交易区间，连续 Merton 点不再可行。BS 连续对冲是零成本理想。惰性不是限价簿，尽管价差可以是成本的来源。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>正的成比例成本使最优变成无交易带，碰壁再调。</li><li>连续再平衡期望成本无穷；工作策略间歇。</li><li>加总可钝化价格对小冲击的反应，与信息惰性不同源。</li><li>出处：Constantinides, <em>JPE</em> 1986；对照 Davis–Norman 奇异控制。</li></ul>',10))])}const T=i(h,[["render",E]]);export{A as __pageData,T as default};
